// ============== 블로그 기사 50편 ==============
// (USUNG_ARTICLES 는 chatbot-articles.js 에서 window 로 주입)
function getArticles(){ return (window.USUNG_ARTICLES||[]); }

// ============== 상태 관리 ==============
const LS = {
  kb:        'usung-chatbot-kb-v1',
  settings:  'usung-chatbot-settings-v1',
  logs:      'usung-chatbot-logs-v1'
};
function loadKB(){
  try { const v = JSON.parse(localStorage.getItem(LS.kb)); if(Array.isArray(v)&&v.length) return v; } catch(e){}
  return JSON.parse(JSON.stringify(DEFAULT_KB));
}
function saveKB(kb){ localStorage.setItem(LS.kb, JSON.stringify(kb)); }
function loadSettings(){
  try { const v = JSON.parse(localStorage.getItem(LS.settings)); if(v&&v.name) return Object.assign({}, DEFAULT_SETTINGS, v); } catch(e){}
  return JSON.parse(JSON.stringify(DEFAULT_SETTINGS));
}
function saveSettings(s){ localStorage.setItem(LS.settings, JSON.stringify(s)); }
function loadLogs(){ try { return JSON.parse(localStorage.getItem(LS.logs))||[]; } catch(e){ return []; } }
function saveLogs(l){ localStorage.setItem(LS.logs, JSON.stringify(l.slice(-500))); }
function appendLog(sess, role, text){
  const logs = loadLogs();
  logs.push({ sess, role, text, t: Date.now() });
  saveLogs(logs);
}

// ============== 매칭 엔진 ==============
function normalize(s){
  return (s||'').toLowerCase().replace(/\s+/g,'').replace(/[.,!?~·/\-_]/g,'');
}
function matchKB(query, kb){
  const qn = normalize(query);
  if(!qn) return null;
  let best = null, bestScore = 0;
  kb.forEach(item=>{
    let score = 0;
    (item.q||[]).forEach(kw=>{
      const k = normalize(kw);
      if(!k) return;
      if(qn.includes(k)) score += k.length * 2;
      // partial jamo match
      else if(k.length>=3 && qn.indexOf(k.slice(0,k.length-1))>=0) score += k.length;
    });
    if(score > bestScore){ bestScore = score; best = item; }
  });
  return bestScore >= 2 ? best : null;
}
function matchArticles(query, n){
  const arts = getArticles();
  if(!arts.length) return [];
  const qn = normalize(query);
  const scored = arts.map(a=>{
    const haystack = normalize(a.t + (a.g||'') + (a.d||''));
    let s = 0;
    // token by token (for Korean, use 2-grams)
    for(let i=0;i<qn.length-1;i++){
      const bg = qn.slice(i,i+2);
      if(haystack.indexOf(bg)>=0) s++;
    }
    return { a, s };
  }).filter(x=>x.s>0).sort((a,b)=>b.s-a.s);
  return scored.slice(0, n||3).map(x=>x.a);
}

// ============== 전화번호 감지 + 자동 문의 등록 ==============
// 한국 전화번호 패턴: 010-1234-5678 / 01012345678 / 010 1234 5678 / 02-123-4567 / 0502-xxx-xxxx
const PHONE_RE = /(0(?:\d{1,2}))[\s\-.]?(\d{3,4})[\s\-.]?(\d{4})/;

function extractPhone(text){
  const m = (text||'').match(PHONE_RE);
  if(!m) return null;
  // normalize to 010-1234-5678 format
  return m[1] + '-' + m[2] + '-' + m[3];
}
// 이름 추출: "저는 김철수입니다", "김철수입니다", "김철수 라고 합니다", 2~4자 한글
function extractName(text){
  const patterns = [
    /저는\s*([가-힣]{2,4})\s*(?:입니다|이라고|라고|예요|이에요)/,
    /이름은\s*([가-힣]{2,4})/,
    /^([가-힣]{2,4})\s*(?:입니다|이라고|라고|예요|이에요)/
  ];
  for(const p of patterns){
    const m = text.match(p);
    if(m) return m[1];
  }
  return null;
}
// 가게/상호 추출: "OOO식당", "OOO고기집", "OOO매장" 등
function extractStore(text){
  const m = text.match(/([가-힣A-Za-z0-9]{2,15}(?:식당|고기집|갈비|정육식당|맛집|매장|가게))/);
  return m ? m[1] : null;
}

// CMS 문의내역에 추가 (admin.html의 S.inquiries와 동일한 localStorage 키 공유)
const CMS_KEY = 'usung-cms-state-v2';
function addCmsInquiry(data){
  let state = null;
  try { state = JSON.parse(localStorage.getItem(CMS_KEY) || 'null'); } catch(e){}
  if(!state) state = { content:{}, arrays:{}, inquiries:[], boards:{}, theme:'dark' };
  if(!Array.isArray(state.inquiries)) state.inquiries = [];

  const inq = {
    id: 'bot_' + Date.now().toString(36),
    nm: data.name || '챗봇 문의자',
    co: data.store || '',
    tel: data.tel || '',
    em: '',
    msg: data.msg || '(챗봇에서 연락처 남김)',
    st: 'new',
    createdAt: Date.now(),
    source: 'chatbot'
  };
  state.inquiries.unshift(inq);
  localStorage.setItem(CMS_KEY, JSON.stringify(state));
  return inq;
}

// 세션별 누적 정보 (이름·가게·전화 조각 조립)
const SESSION_CTX = { tel:null, name:null, store:null, inquiryId:null, lastMsg:'' };

// ============== 챗봇 응답 생성 ==============
function chatRespond(query){
  const kb = loadKB();
  const settings = loadSettings();

  // 0. 전화번호 감지 (최우선) → 문의 자동 등록
  const phone = extractPhone(query);
  const name  = extractName(query);
  const store = extractStore(query);
  if(name)  SESSION_CTX.name  = name;
  if(store) SESSION_CTX.store = store;
  SESSION_CTX.lastMsg = query;

  if(phone){
    SESSION_CTX.tel = phone;
    // 기존 문의가 있으면 업데이트, 없으면 새로 생성
    const inq = addCmsInquiry({
      name:  SESSION_CTX.name,
      store: SESSION_CTX.store,
      tel:   phone,
      msg:   '💬 챗봇 상담 요청 · "' + query + '"'
    });
    SESSION_CTX.inquiryId = inq.id;

    const missing = [];
    if(!SESSION_CTX.name)  missing.push('성함');
    if(!SESSION_CTX.store) missing.push('매장/상호');

    let text = `✅ 연락처 확인했습니다!\n📞 ${phone}\n\n저희 상담원이 가장 빠른 시간 안에 직접 전화드릴게요. 걱정 마시고 편히 기다려 주세요 😊`;
    if(missing.length){
      text += `\n\n혹시 ${missing.join('·')}도 함께 알려주시면 더 정확한 상담 준비가 가능해요. (선택 사항)`;
    }
    text += `\n\n⏰ 평일 09:00~18:00 영업시간 내에 연락드립니다.\n급하신 경우 바로 ${settings.tel} 으로 전화 주세요.`;

    return {
      text,
      cta: 'tel',
      matched: 'phone_detected',
      savedInquiry: true,
      phone
    };
  }

  // 0-1. 이미 전화번호를 남긴 세션에서 이름/가게가 추가로 들어오면 기존 문의 업데이트
  if(SESSION_CTX.tel && (name || store)){
    updateCmsInquiry(SESSION_CTX.inquiryId, { name: SESSION_CTX.name, store: SESSION_CTX.store });
    return {
      text: `감사합니다! ${SESSION_CTX.name?`${SESSION_CTX.name}님, `:''}${SESSION_CTX.store?`<${SESSION_CTX.store}> `:''}정보 잘 받았어요.\n\n상담원에게 전달했으니 곧 ${SESSION_CTX.tel} 으로 연락드리겠습니다 🙏`,
      matched: 'info_updated'
    };
  }

  const hit = matchKB(query, kb);
  const arts = matchArticles(query, 3);

  if(hit){
    return { text: hit.a, cta: hit.cta, link: hit.link, articles: arts, matched: hit.id };
  }
  // no direct match but article hits → suggest reading + fallback CTA
  if(arts.length){
    return {
      text: `"${query}"에 관련된 블로그 글을 찾아봤어요. 아래 글에서 답을 찾으실 수 있을 거예요:\n\n답변을 원하시면 전화번호를 남겨주세요. 상담원이 직접 연락드립니다.`,
      articles: arts,
      cta: 'tel',
      matched: null
    };
  }
  return {
    text: settings.fallback + '\n\n💡 전화번호를 채팅창에 남겨주시면 상담원이 직접 연락드립니다.',
    cta: 'tel',
    matched: null
  };
}

// CMS 문의 업데이트 (이름/가게 추가 정보)
function updateCmsInquiry(id, data){
  if(!id) return;
  let state = null;
  try { state = JSON.parse(localStorage.getItem(CMS_KEY) || 'null'); } catch(e){}
  if(!state || !Array.isArray(state.inquiries)) return;
  const inq = state.inquiries.find(x=>x.id===id);
  if(!inq) return;
  if(data.name)  inq.nm = data.name;
  if(data.store) inq.co = data.store;
  localStorage.setItem(CMS_KEY, JSON.stringify(state));
}

